import os
import sys
import unittest
from pathlib import Path
from unittest.mock import Mock, patch


BACKEND_DIR = str(Path(__file__).resolve().parents[1])
if BACKEND_DIR not in sys.path:
    sys.path.insert(0, BACKEND_DIR)

from services import nvidia_service


class TextProviderTests(unittest.TestCase):
    def test_nvidia_is_preferred_and_receives_system_instruction(self):
        response = Mock()
        response.json.return_value = {
            "choices": [{"message": {"content": "Generated by NVIDIA"}}]
        }

        with (
            patch.dict(
                os.environ,
                {
                    "AI_TEXT_PROVIDER": "nvidia",
                    "NVIDIA_API_KEY": "test-nvidia-key",
                    "NVIDIA_MODEL": "test-model",
                    "GEMINI_API_KEY": "test-gemini-key",
                },
                clear=True,
            ),
            patch.object(nvidia_service.requests, "post", return_value=response) as post,
            patch.object(nvidia_service, "_generate_with_gemini") as gemini,
        ):
            result = nvidia_service.generate_text(
                "User prompt",
                system_instruction="System prompt",
                temperature=0.2,
                max_output_tokens=1200,
            )

        self.assertEqual(result, "Generated by NVIDIA")
        gemini.assert_not_called()
        self.assertEqual(
            post.call_args.kwargs["json"],
            {
                "model": "test-model",
                "messages": [
                    {"role": "system", "content": "System prompt"},
                    {"role": "user", "content": "User prompt"},
                ],
                "max_tokens": 1200,
                "temperature": 0.2,
                "stream": False,
            },
        )

    def test_nvidia_failure_falls_back_to_gemini(self):
        with (
            patch.dict(
                os.environ,
                {
                    "AI_TEXT_PROVIDER": "nvidia",
                    "NVIDIA_API_KEY": "test-nvidia-key",
                    "GEMINI_API_KEY": "test-gemini-key",
                },
                clear=True,
            ),
            patch.object(
                nvidia_service,
                "_generate_with_nvidia",
                side_effect=RuntimeError("NVIDIA unavailable"),
            ),
            patch.object(
                nvidia_service,
                "_generate_with_gemini",
                return_value="Generated by Gemini",
            ) as gemini,
        ):
            result = nvidia_service.generate_text("User prompt")

        self.assertEqual(result, "Generated by Gemini")
        gemini.assert_called_once()

    def test_gemini_failure_falls_back_to_nvidia(self):
        with (
            patch.dict(
                os.environ,
                {
                    "AI_TEXT_PROVIDER": "gemini",
                    "GEMINI_API_KEY": "test-gemini-key",
                    "NVIDIA_API_KEY": "test-nvidia-key",
                },
                clear=True,
            ),
            patch.object(
                nvidia_service,
                "_generate_with_gemini",
                side_effect=RuntimeError("Gemini unavailable"),
            ),
            patch.object(
                nvidia_service,
                "_generate_with_nvidia",
                return_value="Generated by NVIDIA",
            ) as nvidia,
        ):
            result = nvidia_service.generate_text("User prompt")

        self.assertEqual(result, "Generated by NVIDIA")
        nvidia.assert_called_once()

    def test_requires_at_least_one_configured_provider(self):
        with patch.dict(os.environ, {}, clear=True):
            with self.assertRaisesRegex(RuntimeError, "Configure NVIDIA_API_KEY"):
                nvidia_service.generate_text("User prompt")


if __name__ == "__main__":
    unittest.main()
